//! `AudioFormat` protobuf message and encoding metadata.
//!
//! These types are written by hand instead of generated by `protoc`, so the
//! workspace builds with plain `cargo` and no C/C++ protobuf toolchain. Field
//! numbers, types, and enum values mirror `protos/client.proto` exactly.

/// Wire Protocol PCM encoding. The numeric values are frozen at v0.3.4.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum Encoding {
    /// `ENCODING_INVALID = 0`: no valid encoding has been negotiated.
    Invalid = 0,
    /// `ENCODING_PCM_FLOAT = 1`: 32-bit floating-point PCM.
    PcmFloat = 1,
    /// `ENCODING_PCM_8BIT = 2`: 8-bit integer PCM.
    Pcm8Bit = 2,
    /// `ENCODING_PCM_16BIT = 3`: 16-bit integer PCM.
    Pcm16Bit = 3,
    /// `ENCODING_PCM_24BIT = 4`: 24-bit integer PCM, packed in three bytes.
    Pcm24Bit = 4,
    /// `ENCODING_PCM_32BIT = 5`: 32-bit integer PCM.
    Pcm32Bit = 5,
}

impl Encoding {
    /// Every encoding value defined by `client.proto`.
    pub const ALL: [Self; 6] = [
        Self::Invalid,
        Self::PcmFloat,
        Self::Pcm8Bit,
        Self::Pcm16Bit,
        Self::Pcm24Bit,
        Self::Pcm32Bit,
    ];

    /// Size of one sample in bytes, or `None` for `ENCODING_INVALID`.
    pub const fn bytes_per_sample(self) -> Option<usize> {
        match self {
            Self::Invalid => None,
            Self::PcmFloat | Self::Pcm32Bit => Some(4),
            Self::Pcm8Bit => Some(1),
            Self::Pcm16Bit => Some(2),
            Self::Pcm24Bit => Some(3),
        }
    }

    /// The protobuf enum name used by `client.proto`.
    pub const fn proto_name(self) -> &'static str {
        match self {
            Self::Invalid => "ENCODING_INVALID",
            Self::PcmFloat => "ENCODING_PCM_FLOAT",
            Self::Pcm8Bit => "ENCODING_PCM_8BIT",
            Self::Pcm16Bit => "ENCODING_PCM_16BIT",
            Self::Pcm24Bit => "ENCODING_PCM_24BIT",
            Self::Pcm32Bit => "ENCODING_PCM_32BIT",
        }
    }
}

/// `io.github.mkckr0.audio_share_app.pb.AudioFormat` from `client.proto`.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AudioFormat {
    #[prost(enumeration = "Encoding", tag = "1")]
    pub encoding: i32,
    #[prost(int32, tag = "2")]
    pub channels: i32,
    #[prost(int32, tag = "3")]
    pub sample_rate: i32,
}

impl AudioFormat {
    /// Build a format from typed fields.
    pub const fn new(encoding: Encoding, channels: i32, sample_rate: i32) -> Self {
        Self {
            encoding: encoding as i32,
            channels,
            sample_rate,
        }
    }

    /// The typed encoding, or `None` when the peer sent an unknown value.
    pub fn encoding_kind(&self) -> Option<Encoding> {
        Encoding::try_from(self.encoding).ok()
    }

    /// Bytes per sample frame (`bytes_per_sample * channels`).
    ///
    /// Returns `0` for an invalid/unknown encoding or non-positive channel
    /// count. The UDP segmentation code treats `0` as "cannot segment".
    pub fn block_align(&self) -> usize {
        let Some(encoding) = self.encoding_kind() else {
            return 0;
        };
        let Some(bytes_per_sample) = encoding.bytes_per_sample() else {
            return 0;
        };
        if self.channels <= 0 {
            return 0;
        }
        bytes_per_sample.saturating_mul(self.channels as usize)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_encoding_round_trips_and_only_invalid_has_no_sample_size() {
        for encoding in Encoding::ALL {
            assert_eq!(
                Encoding::try_from(encoding as i32),
                Ok(encoding),
                "{encoding:?} must round-trip through the protobuf value"
            );
            assert_eq!(
                encoding.bytes_per_sample().is_some(),
                encoding != Encoding::Invalid,
                "{encoding:?}"
            );
        }
    }
}
